        code: [{ required: true, trigger: "blur", message: "验证码不能为空" }],
      },
      loading: false
    }
  },
  methods: {
    /*passwordValidator(rule, value, callback) {
      const specialChars = '~@#$%^&*()_+';
      const regex = new RegExp(`^[a-zA-Z0-9${specialChars}]*$`);
      if (!regex.test(value) || value.length < 6) {
