    },*/
    handleLogin() {
      // this.$refs.loginFormRef.validate((valid) => {
        // if (valid) {
          // this.loading = true; 
          // login(this.loginData).then((res) => {
            // if (res.code == 200) {
              // sessionStorage.setItem('token', res.token)
              sessionStorage.setItem('token', 123)
              // let devices = res.devices ? JSON.stringify(res.devices) : '[]'
              let devices = `[
                              {"device_name": "信号灯规则", "device_type": "jingShiDeng", "filepath": "/home/ls/UtisWebCfgServer/log/cfg.json"}
                             ]`
              sessionStorage.setItem('devices', devices)
              this.$router.push('webCfg?redirect=jingShiDeng')
            // } else {
            //   this.$message({
            //     message: res.msg,
            //     type: 'error'
            //   });
            // }
          // }).catch(() => {
          // }).finally(() => {
          //   this.loading = false;
          // });
        // }
      // });
    },
    random(min, max) {
      if (!max) {
        max = min;
        min = 0;
      }

      if (min > max) {
        var hold = max;
        max = min;
        min = hold;
      }
      return Math.floor(Math.random() * (max - min + 1)) + min;
    },
    maxOrbit(x, y) {
      var max = Math.max(x, y),
        diameter = Math.round(Math.sqrt(max * max + max * max));
      return diameter / 2;
      //星星移动范围，值越大范围越小，
    },
    init() {
      var canvas = document.getElementById('canvas'),
        ctx = canvas.getContext('2d'),
        w = canvas.width = window.innerWidth,
        h = canvas.height = window.innerHeight,
      
        hue = 217,
        stars = [],
        count = 0,
        maxStars = 2500;//星星数量
      
      var canvas2 = document.createElement('canvas'),
        ctx2 = canvas2.getContext('2d');
      canvas2.width = 100;
      canvas2.height = 100;
      var half = canvas2.width / 2,
        gradient2 = ctx2.createRadialGradient(half, half, 0, half, half, half);
      gradient2.addColorStop(0.025, '#CCC');
      gradient2.addColorStop(0.1, 'hsl(' + hue + ', 61%, 33%)');
      gradient2.addColorStop(0.25, 'hsl(' + hue + ', 64%, 6%)');
      gradient2.addColorStop(1, 'transparent');
      
      ctx2.fillStyle = gradient2;
      ctx2.beginPath();
      ctx2.arc(half, half, half, 0, Math.PI * 2);
      ctx2.fill();
      let that = this
      // End cache
      function setStar() {
        let star = {}
        star.orbitRadius = that.random(that.maxOrbit(w, h))
        star.radius = that.random(60, star.orbitRadius) / 18
        star.orbitX = w / 2
        star.orbitY = h / 2
        star.timePassed = that.random(0, maxStars)
        star.speed = that.random(star.orbitRadius) / 500000
        star.alpha = that.random(2, 10) / 10
        stars[count] = star
        count++
        star.draw = function() {
          var x = Math.sin(this.timePassed) * this.orbitRadius + this.orbitX,
            y = Math.cos(this.timePassed) * this.orbitRadius + this.orbitY,
            twinkle = that.random(10);
        
          if (twinkle === 1 && this.alpha > 0) {
            this.alpha -= 0.05;
          } else if (twinkle === 2 && this.alpha < 1) {
            this.alpha += 0.05;
          }
        
          ctx.globalAlpha = this.alpha;
          ctx.drawImage(canvas2, x - this.radius / 2, y - this.radius / 2, this.radius, this.radius);
          this.timePassed += this.speed;
        }
      }
      function animation() {
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 0.5; //尾巴
        ctx.fillStyle = 'hsla(' + hue + ', 64%, 6%, 2)';
        ctx.fillRect(0, 0, w, h)
        ctx.globalCompositeOperation = 'lighter';
        for (var i = 0, l = stars.length; i < l; i++) {
          stars[i].draw();
        }
        window.requestAnimationFrame(animation);
      }
      for (var i = 0; i < maxStars; i++) {
        setStar();
      }
      animation();
    }
  },
