<template>
  <div class="jsdContianer">
    <el-backtop target=".jsdContianer"></el-backtop>
    <el-button type="primary" plain @click="addRule" style="margin-bottom: 10px;">新增规则</el-button>
    <el-button type="primary" plain @click="initData" style="margin-bottom: 10px;">刷新数据</el-button>
    <div v-if="loading">
      <el-card v-for="(item, index) in allData" :key="index">
        <div slot="header" class="clearfix">
          <el-input v-model="item.name" style="width: 140px" size="small" />
          <el-button style="float: right; padding: 3px 0" type="text" @click="deldetRule(index)" v-if="allData.length > 1">删除规则</el-button>
        </div>
        <div style="display: flex;">
          <el-card style="width: 50%;">
            <div slot="header" class="clearfix">
              <span>条件列表</span>
              <el-button style="float: right; padding: 3px 0" type="text" @click="addConditionList(index)">新增条件</el-button>
            </div>
            <el-card v-for="(v, i) in item.conditionList" :key="i" style="position: relative;">
              <i v-if="item.conditionList.length > 1" style="color: #f74c4c;position: absolute;right: 5px;top: 5px;cursor: pointer;font-size: 25px;" class="el-icon-close" @click="deleteConditionList(index, i)"></i>
              <el-form :inline="true" label-width="90px">
                <el-form-item label="设备类型">
                  <el-select v-model="v.deviceType" style="width: 140px" size="small">
                    <el-option label="灯" :value="0" />
                  </el-select>
                </el-form-item>
                <el-form-item label="设备编号">
                  <el-input-number v-model="v.deviceId" style="width: 140px" size="small" />
                </el-form-item>
                <el-form-item label="条件">
                  <el-select v-model="v.condition" style="width: 140px" size="small" @change="v.args = [{ name: '' }]">
                    <el-option label="判断灯颜色" :value="0" />
                    <el-option label="当前已经亮的时间" :value="1" />
                  </el-select>
                </el-form-item>
                <div v-if="v.condition == 0">
                  <el-form-item label="颜色">
                    <el-select v-model="v.args[0].name" style="width: 140px" size="small">
                      <el-option label="红" :value="0" />
                      <el-option label="绿" :value="1" />
                      <el-option label="黄" :value="2" />
                      <el-option label="黑" :value="3" />
                    </el-select>
                  </el-form-item>
                </div>
                <div  v-else-if="v.condition == 1">
                  <el-form-item label="亮的时间(s)">
                    <el-input-number v-model="v.args[0].name" style="width: 140px;margin-right: 10px;margin-bottom: 10px;" size="small" />
                </el-form-item>
                </div>
                <div v-else>
                  <el-form-item label="参数列表">
                    <el-button type="primary" icon="el-icon-plus" size="mini" @click="addConditionListArgs(index, i)"></el-button>
                  </el-form-item>
                  <div>
                    <div v-for="(arg, argi) in v.args" :key="argi" style="position: relative;display: inline-block;">
                      <el-input v-model="arg.name" style="width: 140px;margin-right: 10px;margin-bottom: 10px;" size="small" />
                      <i style="color: #f74c4c;position: absolute;right: 3px;top: -8px;cursor: pointer;" class="el-icon-error" @click="deleteConditionListArg(index, i, argi)"></i>
                    </div>
                  </div>
                </div>
              </el-form>
            </el-card>
          </el-card>
          <el-card style="width: 50%;">
            <div slot="header" class="clearfix">
              <span>任务列表</span>
              <el-button style="float: right; padding: 3px 0" type="text" @click="addExecuteTaskList(index)">新增任务</el-button>
            </div>
            <el-card v-for="(v, i) in item.executeTaskList" :key="i" style="position: relative;">
              <i v-if="item.executeTaskList.length > 1" style="color: #f74c4c;position: absolute;right: 5px;top: 5px;cursor: pointer;font-size: 25px;" class="el-icon-close" @click="deleteExecuteTaskList(index, i)"></i>
              <el-form :inline="true" label-width="80px">
                <el-form-item label="设备类型">
                  <el-select v-model="v.deviceType" style="width: 140px" size="small">
                    <el-option label="屏幕" :value="1" />
                  </el-select>
                </el-form-item>
                <el-form-item label="设备编号">
                  <el-input-number v-model="v.deviceId" style="width: 140px" size="small" />
                </el-form-item>
                <el-form-item label="任务">
                  <el-select v-model="v.executeTask" style="width: 140px" size="small">
                    <el-option label="屏幕显示图片" :value="0" />
                  </el-select>
                </el-form-item>
                <div>
                  <el-form-item label="参数列表">
                    <el-button type="primary" icon="el-icon-plus" size="mini" @click="addExecuteTaskListArgs(index, i)"></el-button>
                  </el-form-item>
                  <div>
                    <div v-for="(arg, argi) in v.args" :key="argi" style="position: relative;display: inline-block;">
                      <el-input v-model="arg.name" style="width: 140px;margin-right: 10px;margin-bottom: 10px;" size="small" />
                      <i style="color: #f74c4c;position: absolute;right: 3px;top: -8px;cursor: pointer;" class="el-icon-error" @click="deleteExecuteTaskListArg(index, i, argi)"></i>
                    </div>
                  </div>
                </div>
              </el-form>
            </el-card>
          </el-card>
        </div>
      </el-card>
    </div>
    <div style="text-align: center;margin-top: 20px;">
      <el-button type="primary" @click="submit">提交</el-button>
    </div>
  </div>
</template>
<script>
import { getRulesInfo, updateRulesInfo } from '@/api/jingShiDeng'
// import { cryptoJS } from '@/utils/tools';
export default {
  name: 'jingShiDeng',
  data() {
    return {
      allData: [],
      loading: false
    }
  },
  methods: {
    initData() {
      getRulesInfo().then((res) => {
        this.allData = res.rules ? res.rules : []
      })
      this.loading = true
    },
    addRule() {
      this.allData.push({
          "name": "规则1",
          "conditionList": [			// 条件列表
            {
              "deviceType": 0,		// 设备类型 0-灯 1-屏幕
              "deviceId": 1,		// 设备编号 灯编号对应摄像机配置的灯编号
              "condition": 4,		// 条件
              "args": [{ name: '' }]		// 判断条件所需要的参数(字符串列表)
            },
            {
              "deviceType": 0,
              "deviceId": 2,
              "condition": 4,
              "args": [{ name: "" }]
            }
          ],
          "executeTaskList": [    		// 任务列表
            {
              "deviceType": 1,		// 设备类型 0-灯 1-屏幕
              "deviceId": 1,		// 设备编号 目前默认为1 屏幕
              "executeTask": 0,	// 任务 
              "args": [{ name: "" }]	// 执行任务所需要的参数(字符串列表)
            },
            {
              "deviceType": 1,
              "deviceId": 2,
              "executeTask": 0,
              "args": [{ name: "" }]
            }
          ]
        })
    },
    deldetRule(index) {
      this.allData.splice(index, 1)
    },
    addConditionList(index) {
      this.allData[index].conditionList.push({ "deviceType": 0, "deviceId": 1,	"condition": 0, "args": [{ name: "" }] })
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    deleteConditionList(index, i) {
      this.allData[index].conditionList.splice(i, 1)
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    addExecuteTaskList(index) {
      this.allData[index].executeTaskList.push({ "deviceType": 0, "deviceId": 1,	"executeTask": 0, "args": [{ name: "" }] })
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    deleteExecuteTaskList(index, i) {
      this.allData[index].executeTaskList.splice(i, 1)
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    addConditionListArgs(index, i){
      this.allData[index].conditionList[i].args.push({ name: '' })
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    addExecuteTaskListArgs(index, i){
      this.allData[index].executeTaskList[i].args.push({ name: '' })
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    deleteConditionListArg(index, i, argi) {
      this.allData[index].conditionList[i].args.splice(argi, 1)
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    deleteExecuteTaskListArg(index, i, argi) {
      this.allData[index].executeTaskList[i].args.splice(argi, 1)
      this.allData = JSON.parse(JSON.stringify(this.allData))
    },
    submit() {
      updateRulesInfo({ rules: this.allData }).then((res) => {
        this.$message({
          message: res.msg,
          type: 'success'
        });
      })
    }
  },
  mounted() {
    this.initData()
  }
}
</script>
<style lang="less">
.jsdContianer{
  overflow-y: auto;
  height: 92vh;
  .el-card__header{
    padding: 10px;
  }
  .el-card__body{
    padding: 10px;
  }
}
</style>