// src/permission.js

import router from './router'


const whiteList = ['/login'] // 白名单

router.beforeEach(async (to, from, next) => {
  // 判断是否有token
  const hasToken = sessionStorage.getItem('token')
  if (hasToken) {
    if (to.path === '/login') {
      next({ path: '/' })
    } else {
      next()
    }
  } else {
    if (whiteList.includes(to.path)) {
      next()
    } else {
      next('/login')
    }
  }
})